import base64, json
from pathlib import Path
import numpy as np
from PIL import Image, ImageFilter
ROOT=Path(__file__).resolve().parents[1]
TEX=ROOT/'assets'/'textures'; TEX.mkdir(parents=True, exist_ok=True)
BACKDROP_B64=''
(TEX/'cinematic-backdrop.jpg').write_bytes(base64.b64decode(BACKDROP_B64, validate=True))
rng=np.random.default_rng(73); noise=rng.normal(.48,.20,(96,512)).clip(0,1)
small=Image.fromarray((noise*255).astype('uint8'),'L').resize((512,128),Image.Resampling.BICUBIC).filter(ImageFilter.GaussianBlur(8))
a=np.asarray(small,dtype=np.float32)/255.0; y=np.linspace(0,1,128)[:,None]; edge=np.sin(np.clip(y,0,1)*np.pi)**1.8
alpha=(np.clip((a-.30)*1.45,0,1)*edge*210).astype('uint8'); rgba=np.zeros((128,512,4),dtype='uint8'); rgba[:,:,:3]=[132,154,172]; rgba[:,:,3]=alpha
Image.fromarray(rgba,'RGBA').save(TEX/'fog-sheet.png',optimize=True)
w=h=384; yy,xx=np.mgrid[0:h,0:w]; dx=(xx-w/2)/(w/2); dy=(yy-h/2)/(h/2); r=np.sqrt(dx*dx+dy*dy); va=np.clip((r-.45)/.62,0,1)**1.55
v=np.zeros((h,w,4),dtype='uint8'); v[:,:,3]=(va*168).astype('uint8'); Image.fromarray(v,'RGBA').save(TEX/'cinematic-vignette.png',optimize=True)
manifest={'version':'realism-pass-v1','files':['cinematic-backdrop.jpg','fog-sheet.png','cinematic-vignette.png']}
(ROOT/'assets'/'realism-manifest.json').write_text(json.dumps(manifest,indent=2)); print(json.dumps(manifest))
